    print(f"- classes: {report['class_counts']}")
    print(f"- roles: {report['role_counts']}")
    print(f"- source tags: {report['source_tag_counts']}")
    print(f"- sets: {report['set_count']} sets; pieces: {report['set_piece_counts']}")
