def build_animation_event_cue_catalog_report() -> dict:
    raw = load_json(ANIMATION_EVENT_CUES_PATH)
    entries = raw.get("entries", [])
    if not isinstance(entries, list):
        entries = []
    errors: list[str] = []
    warnings: list[str] = []
    event_ids: set[str] = set()
    cue_ids: set[str] = set()
    surface_counts: dict[str, int] = {}
    state_family_counts: dict[str, int] = {}
    playback_policy_counts: dict[str, int] = {}
    blocking_policy_counts: dict[str, int] = {}
    validation_tag_counts: dict[str, int] = {}
    fallback_counts = {"reduced_motion": 0, "fast_mode": 0}
    placeholder_counts = {"vfx": 0, "audio": 0}
    producer_ref_count = 0

    if str(raw.get("schema_id", "")) != ANIMATION_EVENT_CUE_SCHEMA_ID:
        errors.append(f"schema_id must be {ANIMATION_EVENT_CUE_SCHEMA_ID}")
    runtime_policy = raw.get("runtime_policy", {})
    if not isinstance(runtime_policy, dict):
        runtime_policy = {}
        errors.append("runtime_policy must be a dictionary")
    for blocked_flag in (
        "save_version_bump",
        "final_sprite_import",
        "final_vfx_import",
        "final_audio_import",
        "renderer_asset_pipeline",
        "playback_runtime",
        "broad_ui_polish",
    ):
        if bool(runtime_policy.get(blocked_flag, True)):
            errors.append(f"runtime policy must keep {blocked_flag} disabled")

    for entry in entries:
        if not isinstance(entry, dict):
            errors.append("catalog entry must be a dictionary")
            continue
        event_id = str(entry.get("event_id", "")).strip()
        cue_id = str(entry.get("cue_id", "")).strip()
        surface = str(entry.get("surface", "")).strip()
        state_family = str(entry.get("animation_state_family", "")).strip()
        playback_policy = str(entry.get("playback_policy", "")).strip()
        blocking_policy = str(entry.get("blocking_policy", "")).strip()

        missing_fields = sorted(field for field in ANIMATION_EVENT_CUE_REQUIRED_FIELDS if field not in entry)
        if missing_fields:
            errors.append(f"{event_id or '<entry>'} missing fields: {', '.join(missing_fields)}")
        if not event_id:
            errors.append("catalog entry has empty event_id")
        elif event_id in event_ids:
            errors.append(f"duplicate event_id {event_id}")
        else:
            event_ids.add(event_id)
        if not cue_id:
            errors.append(f"{event_id} has empty cue_id")
        elif cue_id in cue_ids:
            errors.append(f"duplicate cue_id {cue_id}")
        else:
            cue_ids.add(cue_id)
        if surface not in ANIMATION_EVENT_CUE_REQUIRED_SURFACES:
            errors.append(f"{event_id} uses unsupported surface {surface}")
        increment_count(surface_counts, surface or "<empty>")
        increment_count(state_family_counts, state_family or "<empty>")
        increment_count(playback_policy_counts, playback_policy or "<empty>")
        increment_count(blocking_policy_counts, blocking_policy or "<empty>")

        fallbacks = entry.get("fallbacks", {})
        if not isinstance(fallbacks, dict):
            errors.append(f"{event_id} fallbacks must be a dictionary")
            fallbacks = {}
        reduced_motion = str(fallbacks.get("reduced_motion_tag", "")).strip()
        fast_mode = str(fallbacks.get("fast_mode_tag", "")).strip()
        if not reduced_motion:
            errors.append(f"{event_id} missing reduced_motion_tag")
        else:
            fallback_counts["reduced_motion"] += 1
        if not fast_mode:
            errors.append(f"{event_id} missing fast_mode_tag")
        else:
            fallback_counts["fast_mode"] += 1

        vfx_ids = string_list(entry.get("vfx_cue_ids", []))
        audio_ids = string_list(entry.get("audio_cue_ids", []))
        if not vfx_ids:
            errors.append(f"{event_id} must define VFX ids or placeholders")
        if not audio_ids:
            errors.append(f"{event_id} must define audio ids or placeholders")
        placeholder_counts["vfx"] += len([cue_id for cue_id in vfx_ids if cue_id.startswith("vfx_placeholder_")])
        placeholder_counts["audio"] += len([cue_id for cue_id in audio_ids if cue_id.startswith("audio_placeholder_")])

        tags = string_list(entry.get("validation_tags", []))
        if not tags:
            errors.append(f"{event_id} missing validation_tags")
        for tag in tags:
            increment_count(validation_tag_counts, tag)
        producer_refs = string_list(entry.get("producer_refs", []))
        if not producer_refs:
            errors.append(f"{event_id} missing producer_refs")
        producer_ref_count += len(producer_refs)
        if not bool(entry.get("skippable", False)):
            warnings.append(f"{event_id} is not skippable")

    for surface in sorted(ANIMATION_EVENT_CUE_REQUIRED_SURFACES):
        if int(surface_counts.get(surface, 0)) <= 0:
            errors.append(f"missing required surface {surface}")
    missing_representatives = sorted(ANIMATION_EVENT_CUE_REPRESENTATIVE_EVENTS - event_ids)
    if missing_representatives:
        errors.append(f"missing representative events: {', '.join(missing_representatives)}")
    for tag in ("battle", "overworld", "town", "spell", "artifact", "ui", "resolved_event"):
        if int(validation_tag_counts.get(tag, 0)) <= 0:
            errors.append(f"missing validation tag {tag}")
    if int(fallback_counts["reduced_motion"]) != len(entries) or int(fallback_counts["fast_mode"]) != len(entries):
        errors.append("every cue entry must include reduced-motion and fast-mode fallbacks")
    if int(state_family_counts.get("move", 0)) <= 0 or int(state_family_counts.get("captured", 0)) <= 0:
        errors.append("catalog must include battle move and overworld capture state families")
    for required_overworld_family in ("route-open", "route-closed", "ambient-loop"):
        if int(state_family_counts.get(required_overworld_family, 0)) <= 0:
            errors.append(f"catalog must include overworld object state family {required_overworld_family}")

    return {
        "ok": not errors,
        "schema": ANIMATION_EVENT_CUE_SCHEMA_ID,
        "mode": "resolved_gameplay_event_to_animation_playback_contract",
        "entry_count": len(entries),
        "surface_counts": surface_counts,
        "state_family_counts": state_family_counts,
        "playback_policy_counts": playback_policy_counts,
        "blocking_policy_counts": blocking_policy_counts,
        "validation_tag_counts": validation_tag_counts,
        "fallback_counts": fallback_counts,
        "placeholder_counts": placeholder_counts,
        "producer_ref_count": producer_ref_count,
        "runtime_policy": runtime_policy,
        "warnings": warnings,
        "errors": errors,
    }


def print_animation_event_cue_catalog_report(report: dict) -> None:
    print("ANIMATION EVENT CUE CATALOG REPORT")
    print(f"- schema: {report['schema']}")
    print(f"- mode: {report['mode']}")
    print(f"- entries: {report['entry_count']}")
    print(f"- surfaces: {report['surface_counts']}")
    print(f"- state families: {report['state_family_counts']}")
    print(f"- fallbacks: {report['fallback_counts']}")
    print(f"- placeholder cues: {report['placeholder_counts']}")
    policy = report.get("runtime_policy", {})
    print(f"- runtime policy: save_version_bump={policy.get('save_version_bump', True)}, final_sprite_import={policy.get('final_sprite_import', True)}, final_vfx_import={policy.get('final_vfx_import', True)}, final_audio_import={policy.get('final_audio_import', True)}, playback_runtime={policy.get('playback_runtime', True)}")
    if report.get("warnings"):
        print(f"- warnings: {report['warnings']}")
    if report.get("errors"):
        print(f"- errors: {report['errors']}")


def normalize_animation_preferences_for_report(preferences: dict | None = None) -> dict:
    preferences = preferences or {}
    accessibility = preferences.get("accessibility", {})
    if not isinstance(accessibility, dict):
        accessibility = {}
    animation = preferences.get("animation", {})
    if not isinstance(animation, dict):
        animation = {}
    gameplay = preferences.get("gameplay", {})
    if not isinstance(gameplay, dict):
        gameplay = {}
    reduced_motion = bool(preferences.get("reduced_motion", preferences.get("reduce_motion", accessibility.get("reduce_motion", accessibility.get("reduced_motion", False)))))
    fast_mode = bool(preferences.get("fast_mode", preferences.get("fast_resolution", gameplay.get("fast_mode", animation.get("fast_mode", False)))))
    mode_hint = str(preferences.get("mode", preferences.get("speed_mode", ""))).strip()
    if mode_hint == "reduced_motion":
        reduced_motion = True
        fast_mode = False
    elif mode_hint in {"fast", "fast_mode"}:
        reduced_motion = False
        fast_mode = True
    elif mode_hint in {"reduced_motion_fast", "combined"}:
        reduced_motion = True
        fast_mode = True
    elif mode_hint == "normal":
        reduced_motion = False
        fast_mode = False
    mode = "normal"
    if reduced_motion and fast_mode:
        mode = "reduced_motion_fast"
    elif reduced_motion:
        mode = "reduced_motion"
    elif fast_mode:
        mode = "fast"
    return {
        "schema_id": ANIMATION_PREFERENCE_POLICY_SCHEMA_ID,
        "mode": mode,
        "reduced_motion": reduced_motion,
        "fast_mode": fast_mode,
        "timing_preference": "fast" if fast_mode else "normal",
        "combined_policy": "reduced_motion_visual_fast_timing" if reduced_motion and fast_mode else "single_preference",
        "max_duration_ms": 180 if fast_mode else (260 if reduced_motion else 700),
    }


def select_animation_policy_case(entry: dict, preferences: dict) -> dict:
    normalized = normalize_animation_preferences_for_report(preferences)
    fallbacks = entry.get("fallbacks", {})
    if not isinstance(fallbacks, dict):
        fallbacks = {}
    selected_fallback = ""
    selected_state = str(entry.get("animation_state", ""))
    visual_policy = "authored_animation_state"
    if normalized["reduced_motion"]:
        selected_fallback = str(fallbacks.get("reduced_motion_tag", "")).strip()
        selected_state = selected_fallback
        visual_policy = "reduced_motion_fallback"
    elif normalized["fast_mode"]:
        selected_fallback = str(fallbacks.get("fast_mode_tag", "")).strip()
        selected_state = selected_fallback
        visual_policy = "fast_mode_fallback"
    selected_blocking = str(entry.get("blocking_policy", ""))
    if normalized["fast_mode"] and selected_blocking in {"input_blocking_timeout", "inherits_source"}:
        selected_blocking = "nonblocking_fast_resolve"
    elif normalized["reduced_motion"] and selected_blocking == "input_blocking_timeout":
        selected_blocking = "nonblocking_reduced_motion"
    return {
        "event_id": str(entry.get("event_id", "")),
        "surface": str(entry.get("surface", "")),
        "subject_kind": str(entry.get("subject_kind", "")),
        "mode": normalized["mode"],
        "selected_animation_state": selected_state,
        "selected_fallback_tag": selected_fallback,
        "selected_visual_policy": visual_policy,
        "selected_playback_policy": "fast_resolve" if normalized["fast_mode"] else str(entry.get("playback_policy", "")),
        "selected_blocking_policy": selected_blocking,
        "timing_preference": normalized["timing_preference"],
        "combined_policy": normalized["combined_policy"],
        "max_duration_ms": normalized["max_duration_ms"],
    }


def build_animation_preference_policy_report() -> dict:
    raw = load_json(ANIMATION_EVENT_CUES_PATH)
    entries = raw.get("entries", [])
    if not isinstance(entries, list):
        entries = []
    by_event = {str(entry.get("event_id", "")): entry for entry in entries if isinstance(entry, dict)}
    errors: list[str] = []
    preference_cases = {
        "normal": {},
        "reduced_motion": {"reduced_motion": True},
        "fast": {"fast_mode": True},
        "reduced_motion_fast": {"reduced_motion": True, "fast_mode": True},
    }
    selected_cases: dict[str, dict] = {}
    covered_surfaces: dict[str, int] = {}
    covered_subjects: dict[str, int] = {}
    reduced_count = 0
    fast_count = 0
    combined_count = 0
    troop_count = 0
    object_count = 0

    preference_policy = raw.get("preference_policy", {})
    if not isinstance(preference_policy, dict):
        errors.append("preference_policy must be a dictionary")
    elif str(preference_policy.get("schema_id", "")) != ANIMATION_PREFERENCE_POLICY_SCHEMA_ID:
        errors.append(f"preference_policy.schema_id must be {ANIMATION_PREFERENCE_POLICY_SCHEMA_ID}")

    for event_id in sorted(ANIMATION_POLICY_REPRESENTATIVE_EVENTS):
        entry = by_event.get(event_id)
        if not isinstance(entry, dict):
            errors.append(f"missing representative policy event {event_id}")
            continue
        event_cases = {}
        fallbacks = entry.get("fallbacks", {})
        if not isinstance(fallbacks, dict):
            fallbacks = {}
        for mode, preferences in preference_cases.items():
            selected = select_animation_policy_case(entry, preferences)
            event_cases[mode] = selected
            if mode == "reduced_motion" and selected["selected_fallback_tag"] == str(fallbacks.get("reduced_motion_tag", "")).strip():
                reduced_count += 1
            if mode == "fast" and selected["selected_fallback_tag"] == str(fallbacks.get("fast_mode_tag", "")).strip():
                fast_count += 1
            if mode == "reduced_motion_fast" and selected["selected_fallback_tag"] == str(fallbacks.get("reduced_motion_tag", "")).strip() and selected["timing_preference"] == "fast":
                combined_count += 1
        selected_cases[event_id] = event_cases
        increment_count(covered_surfaces, str(entry.get("surface", "")) or "<empty>")
        subject = str(entry.get("subject_kind", "")) or "<empty>"
        increment_count(covered_subjects, subject)
        if subject == "troop_stack":
            troop_count += 1
        if subject == "map_object":
            object_count += 1

    for surface in sorted(ANIMATION_EVENT_CUE_REQUIRED_SURFACES):
        if int(covered_surfaces.get(surface, 0)) <= 0:
            errors.append(f"missing policy surface coverage for {surface}")
    representative_count = len(ANIMATION_POLICY_REPRESENTATIVE_EVENTS)
    if troop_count < 4:
        errors.append("policy report must cover at least four battle troop cues")
    if object_count < 4:
        errors.append("policy report must cover at least four overworld map-object cues")
    if reduced_count != representative_count:
        errors.append("reduced-motion policy fallback selection is incomplete")
    if fast_count != representative_count:
        errors.append("fast-mode policy fallback selection is incomplete")
    if combined_count != representative_count:
        errors.append("combined policy must use reduced-motion visuals with fast timing")

    return {
        "ok": not errors,
        "schema": ANIMATION_PREFERENCE_POLICY_SCHEMA_ID,
        "mode": "cue_playback_preference_policy",
        "representative_event_count": representative_count,
        "covered_surfaces": covered_surfaces,
        "covered_subjects": covered_subjects,
        "troop_policy_count": troop_count,
        "object_policy_count": object_count,
        "reduced_motion_policy_count": reduced_count,
        "fast_mode_policy_count": fast_count,
        "combined_policy_count": combined_count,
        "selected_cases": selected_cases,
        "runtime_policy": raw.get("runtime_policy", {}) if isinstance(raw.get("runtime_policy", {}), dict) else {},
        "errors": errors,
    }


def print_animation_preference_policy_report(report: dict) -> None:
    print("ANIMATION REDUCED-MOTION FAST-MODE POLICY REPORT")
    print(f"- schema: {report['schema']}")
    print(f"- mode: {report['mode']}")
    print(f"- representative events: {report['representative_event_count']}")
    print(f"- surfaces: {report['covered_surfaces']}")
    print(f"- subjects: {report['covered_subjects']}")
    print(f"- policy counts: reduced={report['reduced_motion_policy_count']}, fast={report['fast_mode_policy_count']}, combined={report['combined_policy_count']}")
    if report.get("errors"):
        print(f"- errors: {report['errors']}")


def build_animation_battle_troop_state_contract_report() -> dict:
    raw = load_json(ANIMATION_EVENT_CUES_PATH)
    entries = raw.get("entries", [])
    if not isinstance(entries, list):
        entries = []
    catalog_report = build_animation_event_cue_catalog_report()
    errors: list[str] = list(catalog_report.get("errors", []))
    by_event = {str(entry.get("event_id", "")): entry for entry in entries if isinstance(entry, dict)}
    battle_entries = [
        entry for entry in entries
        if isinstance(entry, dict)
        and str(entry.get("surface", "")) == "battle"
        and str(entry.get("subject_kind", "")) == "troop_stack"
    ]
    state_family_counts: dict[str, int] = {}
    fallback_counts = {"reduced_motion": 0, "fast_mode": 0}
    producer_ref_count = 0
    representative_events: dict[str, str] = {}
    policy_cases: dict[str, dict] = {}

    for entry in battle_entries:
        increment_count(state_family_counts, str(entry.get("animation_state_family", "")) or "<empty>")
        fallbacks = entry.get("fallbacks", {})
        if not isinstance(fallbacks, dict):
            fallbacks = {}
        if str(fallbacks.get("reduced_motion_tag", "")).strip():
            fallback_counts["reduced_motion"] += 1
        if str(fallbacks.get("fast_mode_tag", "")).strip():
            fallback_counts["fast_mode"] += 1
        producer_ref_count += len(string_list(entry.get("producer_refs", [])))

    for family, event_id in sorted(ANIMATION_BATTLE_TROOP_REPRESENTATIVE_EVENTS.items()):
        entry = by_event.get(event_id)
        if not isinstance(entry, dict):
            errors.append(f"battle troop family {family} missing representative event {event_id}")
            continue
        representative_events[family] = event_id
        if str(entry.get("surface", "")) != "battle":
            errors.append(f"{event_id} must use battle surface")
        if str(entry.get("subject_kind", "")) != "troop_stack":
            errors.append(f"{event_id} must use troop_stack subject_kind")
        if str(entry.get("animation_state_family", "")) != family:
            errors.append(f"{event_id} must map to state family {family}")
        tags = set(string_list(entry.get("validation_tags", [])))
        for required_tag in ("battle", "troop_state", "resolved_event"):
            if required_tag not in tags:
                errors.append(f"{event_id} missing validation tag {required_tag}")
        if not string_list(entry.get("producer_refs", [])):
            errors.append(f"{event_id} must define producer refs")
        fallbacks = entry.get("fallbacks", {})
        if not isinstance(fallbacks, dict):
            fallbacks = {}
        reduced_fallback = str(fallbacks.get("reduced_motion_tag", "")).strip()
        fast_fallback = str(fallbacks.get("fast_mode_tag", "")).strip()
        if not reduced_fallback:
            errors.append(f"{event_id} missing reduced-motion fallback")
        if not fast_fallback:
            errors.append(f"{event_id} missing fast-mode fallback")
        if not bool(entry.get("skippable", False)):
            errors.append(f"{event_id} must remain skippable")

        event_cases = {
            "normal": select_animation_policy_case(entry, {}),
            "reduced_motion": select_animation_policy_case(entry, {"reduced_motion": True}),
            "fast": select_animation_policy_case(entry, {"fast_mode": True}),
            "reduced_motion_fast": select_animation_policy_case(entry, {"reduced_motion": True, "fast_mode": True}),
        }
        if event_cases["reduced_motion"]["selected_fallback_tag"] != reduced_fallback:
            errors.append(f"{event_id} reduced-motion policy did not select reduced fallback")
        if event_cases["fast"]["selected_fallback_tag"] != fast_fallback:
            errors.append(f"{event_id} fast-mode policy did not select fast fallback")
        if event_cases["reduced_motion_fast"]["selected_fallback_tag"] != reduced_fallback or event_cases["reduced_motion_fast"]["timing_preference"] != "fast":
            errors.append(f"{event_id} combined policy must use reduced visuals with fast timing")
        policy_cases[event_id] = event_cases

    for family in sorted(ANIMATION_BATTLE_TROOP_REQUIRED_STATE_FAMILIES):
        if int(state_family_counts.get(family, 0)) <= 0:
            errors.append(f"missing battle troop state family {family}")
    if fallback_counts["reduced_motion"] != len(battle_entries) or fallback_counts["fast_mode"] != len(battle_entries):
        errors.append("battle troop entries must all define reduced-motion and fast-mode fallbacks")

    return {
        "ok": not errors,
        "schema": ANIMATION_BATTLE_TROOP_STATE_CONTRACT_SCHEMA_ID,
        "mode": "battle_troop_event_to_sprite_state_contract",
        "required_state_families": sorted(ANIMATION_BATTLE_TROOP_REQUIRED_STATE_FAMILIES),
        "representative_events": representative_events,
        "battle_troop_entry_count": len(battle_entries),
        "state_family_counts": state_family_counts,
        "fallback_counts": fallback_counts,
        "producer_ref_count": producer_ref_count,
        "policy_cases": policy_cases,
        "runtime_policy": raw.get("runtime_policy", {}) if isinstance(raw.get("runtime_policy", {}), dict) else {},
        "errors": errors,
    }


def animation_overworld_object_required_tags(family: str) -> set[str]:
    tags = {"overworld", "object_state", family}
    if family not in {"idle", "active", "ambient-loop"}:
        tags.add("resolved_event")
    if family == "ambient-loop":
        tags.add("reduced_motion_loop")
    return tags


def animation_overworld_object_content_context() -> dict:
    map_objects = load_json(CONTENT_DIR / "map_objects.json")
    resource_sites = load_json(CONTENT_DIR / "resource_sites.json")
    object_items = map_objects.get("items", []) if isinstance(map_objects, dict) else []
    site_items = resource_sites.get("items", []) if isinstance(resource_sites, dict) else []
    object_class_counts: dict[str, int] = {}
    linked_resource_site_count = 0
    guarded_site_count = 0
    persistent_site_count = 0
    repeatable_site_count = 0
    for obj in object_items:
        if not isinstance(obj, dict):
            continue
        family = str(obj.get("family", "")).strip() or "<empty>"
        increment_count(object_class_counts, family)
        if str(obj.get("resource_site_id", "")).strip():
            linked_resource_site_count += 1
    for site in site_items:
        if not isinstance(site, dict):
            continue
        if bool(site.get("guarded", False)):
            guarded_site_count += 1
        control_income = site.get("control_income", {})
        if not isinstance(control_income, dict):
            control_income = {}
        if bool(site.get("persistent", False)) or bool(control_income):
            persistent_site_count += 1
        if bool(site.get("repeatable", False)) or int(site.get("refresh_days", 0) or 0) > 0:
            repeatable_site_count += 1
    return {
        "object_class_counts": object_class_counts,
        "linked_resource_site_count": linked_resource_site_count,
        "guarded_site_count": guarded_site_count,
        "persistent_site_count": persistent_site_count,
        "repeatable_site_count": repeatable_site_count,
    }


def build_animation_overworld_object_state_contract_report() -> dict:
    raw = load_json(ANIMATION_EVENT_CUES_PATH)
    entries = raw.get("entries", [])
    if not isinstance(entries, list):
        entries = []
    catalog_report = build_animation_event_cue_catalog_report()
    errors: list[str] = list(catalog_report.get("errors", []))
    by_event = {str(entry.get("event_id", "")): entry for entry in entries if isinstance(entry, dict)}
    object_entries = [
        entry for entry in entries
        if isinstance(entry, dict)
        and str(entry.get("surface", "")) == "overworld"
        and str(entry.get("subject_kind", "")) in {"map_object", "resource_site", "route"}
    ]
    town_shared_entries = [
        entry for entry in entries
        if isinstance(entry, dict)
        and str(entry.get("surface", "")) == "town"
        and str(entry.get("subject_kind", "")) == "town"
        and str(entry.get("animation_state_family", "")) in {"captured", "visited"}
    ]
    state_family_counts: dict[str, int] = {}
    subject_counts: dict[str, int] = {}
    fallback_counts = {"reduced_motion": 0, "fast_mode": 0}
    producer_ref_count = 0
    representative_events: dict[str, str] = {}
    policy_cases: dict[str, dict] = {}

    for entry in object_entries:
        increment_count(state_family_counts, str(entry.get("animation_state_family", "")) or "<empty>")
        subject = str(entry.get("subject_kind", "")) or "<empty>"
        increment_count(subject_counts, subject)
        fallbacks = entry.get("fallbacks", {})
        if not isinstance(fallbacks, dict):
            fallbacks = {}
        if str(fallbacks.get("reduced_motion_tag", "")).strip():
            fallback_counts["reduced_motion"] += 1
        if str(fallbacks.get("fast_mode_tag", "")).strip():
            fallback_counts["fast_mode"] += 1
        producer_ref_count += len(string_list(entry.get("producer_refs", [])))

    for family, event_id in sorted(ANIMATION_OVERWORLD_OBJECT_REPRESENTATIVE_EVENTS.items()):
        entry = by_event.get(event_id)
        if not isinstance(entry, dict):
            errors.append(f"overworld object family {family} missing representative event {event_id}")
            continue
        representative_events[family] = event_id
        if str(entry.get("surface", "")) != "overworld":
            errors.append(f"{event_id} must use overworld surface")
        if str(entry.get("subject_kind", "")) not in {"map_object", "resource_site", "route"}:
            errors.append(f"{event_id} must use map_object, resource_site, or route subject_kind")
        if str(entry.get("animation_state_family", "")) != family:
            errors.append(f"{event_id} must map to state family {family}")
        tags = set(string_list(entry.get("validation_tags", [])))
        for required_tag in sorted(animation_overworld_object_required_tags(family)):
            if required_tag not in tags:
                errors.append(f"{event_id} missing validation tag {required_tag}")
        if not string_list(entry.get("producer_refs", [])):
            errors.append(f"{event_id} must define producer refs")
        fallbacks = entry.get("fallbacks", {})
        if not isinstance(fallbacks, dict):
            fallbacks = {}
        reduced_fallback = str(fallbacks.get("reduced_motion_tag", "")).strip()
        fast_fallback = str(fallbacks.get("fast_mode_tag", "")).strip()
        if not reduced_fallback:
            errors.append(f"{event_id} missing reduced-motion fallback")
        if not fast_fallback:
            errors.append(f"{event_id} missing fast-mode fallback")
        if not bool(entry.get("skippable", False)):
            errors.append(f"{event_id} must remain skippable")

        event_cases = {
            "normal": select_animation_policy_case(entry, {}),
            "reduced_motion": select_animation_policy_case(entry, {"reduced_motion": True}),
            "fast": select_animation_policy_case(entry, {"fast_mode": True}),
            "reduced_motion_fast": select_animation_policy_case(entry, {"reduced_motion": True, "fast_mode": True}),
        }
        if event_cases["reduced_motion"]["selected_fallback_tag"] != reduced_fallback:
            errors.append(f"{event_id} reduced-motion policy did not select reduced fallback")
        if event_cases["fast"]["selected_fallback_tag"] != fast_fallback:
            errors.append(f"{event_id} fast-mode policy did not select fast fallback")
        if event_cases["reduced_motion_fast"]["selected_fallback_tag"] != reduced_fallback or event_cases["reduced_motion_fast"]["timing_preference"] != "fast":
            errors.append(f"{event_id} combined policy must use reduced visuals with fast timing")
        policy_cases[event_id] = event_cases

    for family in sorted(ANIMATION_OVERWORLD_OBJECT_REQUIRED_STATE_FAMILIES):
        if int(state_family_counts.get(family, 0)) <= 0:
            errors.append(f"missing overworld object state family {family}")
    for subject in ("map_object", "resource_site"):
        if int(subject_counts.get(subject, 0)) <= 0:
            errors.append(f"missing overworld object subject_kind {subject}")
    if not town_shared_entries:
        errors.append("missing shared town object-state hook")
    if fallback_counts["reduced_motion"] != len(object_entries) or fallback_counts["fast_mode"] != len(object_entries):
        errors.append("overworld object entries must all define reduced-motion and fast-mode fallbacks")

    content_context = animation_overworld_object_content_context()
    content_classes = content_context.get("object_class_counts", {})
    if not isinstance(content_classes, dict):
        content_classes = {}
    for object_class in ("pickup", "mine", "neutral_dwelling", "guarded_reward_site", "transit_object", "blocker", "faction_landmark"):
        if int(content_classes.get(object_class, 0)) <= 0:
            errors.append(f"missing object content class {object_class}")
    if int(content_context.get("guarded_site_count", 0)) <= 0:
        errors.append("content context must include guarded resource sites")
    if int(content_context.get("persistent_site_count", 0)) <= 0:
        errors.append("content context must include persistent resource sites")
    if int(content_context.get("repeatable_site_count", 0)) <= 0:
        errors.append("content context must include repeatable resource sites")

    return {
        "ok": not errors,
        "schema": ANIMATION_OVERWORLD_OBJECT_STATE_CONTRACT_SCHEMA_ID,
        "mode": "overworld_object_event_to_state_contract",
        "required_state_families": sorted(ANIMATION_OVERWORLD_OBJECT_REQUIRED_STATE_FAMILIES),
        "representative_events": representative_events,
        "overworld_object_entry_count": len(object_entries),
        "town_shared_entry_count": len(town_shared_entries),
        "state_family_counts": state_family_counts,
        "subject_counts": subject_counts,
        "fallback_counts": fallback_counts,
        "producer_ref_count": producer_ref_count,
        "content_context": content_context,
        "policy_cases": policy_cases,
        "runtime_policy": raw.get("runtime_policy", {}) if isinstance(raw.get("runtime_policy", {}), dict) else {},
        "errors": errors,
    }


