def validate_packaging_release_candidate_pipeline(errors: list[str]) -> None:
    for path in (
        RELEASE_CANDIDATE_TOOL_PATH,
        RELEASE_CANDIDATE_TEST_PATH,
        RELEASE_CANDIDATE_WORKFLOW_PATH,
        RELEASE_DELIVERY_POLICY_TOOL_PATH,
        RELEASE_DELIVERY_POLICY_TEST_PATH,
        RELEASE_PROMOTION_TOOL_PATH,
        RELEASE_PROMOTION_TEST_PATH,
        RELEASE_PROMOTION_WORKFLOW_PATH,
    ):
        ensure(path.exists(), errors, f"Missing release-candidate pipeline file: {path.relative_to(ROOT)}")

    if RELEASE_CANDIDATE_TOOL_PATH.exists():
        tool_text = RELEASE_CANDIDATE_TOOL_PATH.read_text(encoding="utf-8")
        for required_token in (
            "heroes_like_release_candidate_v1",
            "release candidate requires a clean tracked worktree",
            "release candidate found unexpected untracked source",
            "requested source revision does not match checked-out HEAD",
            "configure_linux_release",
            "build_linux_release",
            "selftest_linux_release",
            "configure_windows_release",
            "-DCMAKE_SYSTEM_NAME=Windows",
            "-DCMAKE_SYSTEM_PROCESSOR=x86_64",
            "build_windows_release",
            "selftest_windows_release",
            "parse_project",
            "validate_repository",
            "package_release",
            "verify_release",
            "native release output is stale",
            'protect_owned_directory(build_root, "native build root")',
            "release-candidate-result.json",
            "SOURCE_DATE_EPOCH",
            "RELEASE_SOURCE_REVISION",
        ):
            ensure(required_token in tool_text, errors, f"Release-candidate driver is missing required token: {required_token}")

    if RELEASE_CANDIDATE_TEST_PATH.exists():
        test_text = RELEASE_CANDIDATE_TEST_PATH.read_text(encoding="utf-8")
        for required_token in (
            "test_command_plan_rebuilds_and_tests_both_platforms_before_packaging",
            "test_revision_must_be_full_lowercase_git_object_id",
            "test_source_revision_rejects_mismatched_head_and_dirty_checkout",
            "test_native_output_rejects_stale_and_wrong_architecture_payloads",
            "test_pe_validation_accepts_only_x86_64",
            "test_release_output_reset_refuses_repository_paths",
            "test_workflow_uses_clean_recursive_checkout_and_single_driver",
            "test_workflow_delivers_only_fail_closed_draft_prereleases",
        ):
            ensure(required_token in test_text, errors, f"Release-candidate focused test is missing required token: {required_token}")

    if RELEASE_CANDIDATE_WORKFLOW_PATH.exists():
        workflow_text = RELEASE_CANDIDATE_WORKFLOW_PATH.read_text(encoding="utf-8")
        for required_token in (
            "workflow_dispatch:",
            '"v[0-9]*"',
            "permissions:",
            "contents: read",
            "actions/checkout@v6",
            "submodules: recursive",
            "actions/setup-python@v5",
            "Godot_v${GODOT_VERSION}_linux.x86_64.zip",
            "Godot_v${GODOT_VERSION}_export_templates.tpz",
            "mingw-w64",
            "wine64",
            "tools/build_release_candidate.py",
            '--source-revision "$RELEASE_SOURCE_REVISION"',
            "actions/upload-artifact@v7",
            "if-no-files-found: error",
            "create_draft_release:",
            "create-draft-prerelease:",
            "tools/resolve_release_delivery.py",
            "if: needs.build-release-candidate.outputs.deliver_draft == 'true'",
            "actions/download-artifact@v8",
            "Verify downloaded candidate identity",
            "sha256sum --check SHA256SUMS",
            "gh api --include",
            "Could not prove release $RELEASE_TAG is absent.",
            "gh release create",
            "--draft",
            "--prerelease",
            "--latest=false",
            "--verify-tag",
            '--target "$GITHUB_SHA"',
        ):
            ensure(required_token in workflow_text, errors, f"Release-candidate workflow is missing required token: {required_token}")
        for forbidden_token in (
            "softprops/action-gh-release",
            "--clobber",
            "--draft=false",
        ):
            ensure(forbidden_token not in workflow_text, errors, f"Release-candidate workflow has unsafe release behavior: {forbidden_token}")
        ensure(
            workflow_text.count("contents: write") == 1,
            errors,
            "Release-candidate workflow must grant contents write to exactly one delivery job",
        )

    if RELEASE_PROMOTION_TOOL_PATH.exists():
        promotion_text = RELEASE_PROMOTION_TOOL_PATH.read_text(encoding="utf-8")
        for required_token in (
            "heroes_like_release_promotion_verification_v1",
            "public prerelease promotion requires a SemVer prerelease tag",
            "release promotion must run from refs/heads/main",
            "release target commit does not match the exact tag revision",
            "release asset set mismatch",
            "downloaded asset set mismatch",
            "SHA256SUMS must contain exactly the four packaged payloads",
            "release or asset identity changed during promotion",
            "promotion_fingerprint",
        ):
            ensure(required_token in promotion_text, errors, f"Release-promotion verifier is missing required token: {required_token}")

    if RELEASE_PROMOTION_TEST_PATH.exists():
        promotion_test_text = RELEASE_PROMOTION_TEST_PATH.read_text(encoding="utf-8")
        for required_token in (
            "test_policy_requires_manual_main_prerelease_and_exact_confirmation",
            "test_full_draft_and_public_verification_preserve_fingerprint",
            "test_cli_writes_a_full_verification_result",
            "test_release_metadata_rejects_state_revision_and_asset_identity_drift",
            "test_payload_rejects_schema_version_size_and_checksum_drift",
            "test_post_publish_fingerprint_rejects_asset_replacement",
            "test_workflow_is_manual_prerelease_only_and_reverifies_after_publish",
        ):
            ensure(required_token in promotion_test_text, errors, f"Release-promotion focused test is missing required token: {required_token}")

    if RELEASE_PROMOTION_WORKFLOW_PATH.exists():
        promotion_workflow_text = RELEASE_PROMOTION_WORKFLOW_PATH.read_text(encoding="utf-8")
        for required_token in (
            "workflow_dispatch:",
            "confirmation:",
            "contents: read",
            "contents: write",
            "actions/checkout@v6",
            "if: github.ref == 'refs/heads/main'",
            "ref: main",
            "tools/verify_release_promotion.py",
            "--policy-only",
            '--workflow-ref "$GITHUB_REF"',
            "draft-prerelease",
            "public-prerelease",
            "releases/assets/$asset_id",
            "gh release edit",
            "--draft=false",
            "--prerelease",
            "--latest=false",
            "--expected-fingerprint",
        ):
            ensure(required_token in promotion_workflow_text, errors, f"Release-promotion workflow is missing required token: {required_token}")
        for forbidden_token in (
            "push:",
            "schedule:",
            "gh release create",
            "gh release upload",
            "gh release download",
            "gh release delete",
            "--clobber",
            "--latest=true",
            "tools/build_release_candidate.py",
            "tools/package_release.py",
            "actions/upload-artifact",
        ):
            ensure(forbidden_token not in promotion_workflow_text, errors, f"Release-promotion workflow has unsafe behavior: {forbidden_token}")
        ensure(
            promotion_workflow_text.count("contents: write") == 1,
            errors,
            "Release-promotion workflow must grant contents write to exactly one promotion job",
        )
        ensure(
            promotion_workflow_text.count("releases/assets/$asset_id") == 2,
            errors,
            "Release-promotion workflow must download exact validated asset ids before and after publication",
        )
        ensure(
            promotion_workflow_text.count("gh release edit") == 1,
            errors,
            "Release-promotion workflow must have exactly one publication command",
        )


